# app/api/links.py from datetime import datetime, timezone from fastapi import Depends, status from sqlalchemy.orm import Session from app.db import get_db from app.models.link import Link from app.schemas.link import LinkCreate, LinkRead
@router.post("/links", response_model=LinkRead, status_code=status.HTTP_201_CREATED) def create_link(payload: LinkCreate, db: Session = Depends(get_db)) -> Link: ...
# POST /links # 201 -> LinkRead {id: int, url: str, title: str | null, created_at: datetime} # 422 -> raised by LinkCreate before the handler runs; nothing is stored # # created_at is stored as NAIVE UTC (tzinfo stripped), so L3-004 can order by it # directly with `order_by(Link.created_at.desc())` without mixing aware and naive # values. # # Duplicate urls are permitted: two POSTs of the same url create two rows. # # For L3-004 and L3-006, which reopen this file: the module now imports # get_db, Link, LinkCreate, LinkRead, Session, Depends, status and datetime/timezone. # Add to those imports rather than replacing them, and leave create_link untouched.
